<script setup lang="ts">
import {ref,watch,computed} from 'vue';import {useRoute} from 'vue-router';
import {relationEndpoint,api,mutate,text,date,can,opts,useTask,type DTO,type Page} from './shared';import {useForm} from './forms';import TaskForm from './TaskForm.vue';import PageState from './PageState.vue';import Pager from './Pager.vue';import CredentialPanel from './CredentialPanel.vue';import MaterialsPanel from './MaterialsPanel.vue';
const route=useRoute(),{busy,error,notice,run}=useTask(),{form,open}=useForm();const platform=ref<DTO<'Stage2CatalogView'>>(),row=ref<DTO<'ResourceView'>>(),section=ref('facts'),related=ref<DTO<'Stage2ResourceRelationView'>[]>([]),bindings=ref<DTO<'Stage2BindingView'>[]>([]),declarations=ref<DTO<'Stage2DeclarationView'>[]>([]),history=ref<DTO<'Stage2HistoryView'>[]>([]),sources=ref<DTO<'Stage2SourceView'>[]>([]),page=ref(1),total=ref(0),more=ref(false);
const id=computed(()=>String(route.params.id));const editable=computed(()=>Boolean(row.value?.capabilities.edit));
const fieldNames:Record<string,string>={plan:'套餐',seats:'席位数',billing_cycle:'计费周期',expires_on:'到期日',external_key_id:'外部密钥标识',external_instance_id:'外部实例标识',environment:'环境',region:'区域',scope_label:'业务范围',endpoint:'访问地址',tech_stack:'技术栈',metric_scope:'指标范围',resource_kind:'云资源类型',specification:'规格',domain_name:'域名',registrar:'注册商',registered_on:'注册日',renewal_note:'续期说明'};
async function load(){await run(async()=>{row.value=await api.get<DTO<'ResourceView'>>('/resources/'+id.value);platform.value=row.value.platform_id?await api.get<DTO<'Stage2CatalogView'>>('/directory/platform/'+row.value.platform_id):undefined;});}
async function extra(){await run(async()=>{if(section.value==='relations'){const [r,d]=await Promise.all([api.get<Page<DTO<'Stage2ResourceRelationView'>>>(`/resources/${id.value}/relations?include_history=true&page=${page.value}`),api.get<Page<DTO<'Stage2DeclarationView'>>>(`/resources/${id.value}/relation-declarations?page=${page.value}`)]);related.value=r.items;declarations.value=d.items;total.value=r.pagination.total;more.value=r.pagination.has_next||d.pagination.has_next;}else if(section.value==='history'){const [h,s]=await Promise.all([api.get<Page<DTO<'Stage2HistoryView'>>>(`/resources/${id.value}/history?page=${page.value}`),api.get<Page<DTO<'Stage2SourceView'>>>(`/resources/${id.value}/sources?page=${page.value}`)]);history.value=h.items;sources.value=s.items;total.value=h.pagination.total;more.value=h.pagination.has_next||s.pagination.has_next;}else if(section.value==='bindings'){const b=await api.get<Page<DTO<'Stage2BindingView'>>>(`/resources/${id.value}/bindings?page=${page.value}`);bindings.value=b.items;total.value=b.pagination.total;more.value=b.pagination.has_next;}});}
watch(id,()=>{row.value=undefined;section.value=['facts','relations','bindings','materials','credentials','history'].includes(String(route.query.section))?String(route.query.section):'facts';void load();},{immediate:true});watch(section,()=>{page.value=1;void extra();});
async function changed(){await load();window.dispatchEvent(new Event('v3:changed'));}
function edit(){const r=row.value!;open({title:'编辑资源资料',onRefresh:async()=>{const latest=await api.get<DTO<'ResourceView'>>('/resources/'+r.id);Object.assign(r,latest);return `服务器最新版本 v${latest.version}：名称 ${latest.name}；提供方 ${latest.provider_name??'未填'}；用途 ${latest.purpose??'未填'}`;},description:'已确认的责任、归属和生命周期通过流程治理变更。此处仅修订描述资料。',fields:[{key:'name',label:'名称',required:true,initial:r.name},{key:'provider_name',label:'提供方',initial:r.provider_name??''},{key:'purpose',label:'用途',type:'textarea',initial:r.purpose??''},...Object.entries(r.attributes).filter(([key])=>fieldNames[key]).map(([key,value])=>({key:'attr_'+key,label:fieldNames[key],initial:Array.isArray(value)?value.join(','):String(value??''),type:key.endsWith('_on')?'date':key==='seats'?'number':'text'}))],onSubmit:async v=>{const attributes:Record<string,unknown>={...r.attributes};for(const [key,value] of Object.entries(v))if(key.startsWith('attr_')){const name=key.slice(5);attributes[name]=name==='tech_stack'?value.split(/[,，]/).map(s=>s.trim()).filter(Boolean):name==='seats'?(value?Number(value):null):value||null;}const changes:DTO<'ResourcePatch'>={expected_version:r.version,changes:{name:v.name,provider_name:v.provider_name||null,purpose:v.purpose||null,attributes}};await mutate('/resources/'+r.id,changes,'PATCH');await load();}});}
function action(action:string){const r=row.value!;open({title:({verify:'核实资源','confirm-lifecycle':'确认初始生命周期',archive:'归档资源',unarchive:'恢复归档'}[action]??action),description:'依据实际情况填写；不会自动执行外部系统操作。',fields:[...(action==='confirm-lifecycle'?[{key:'lifecycle',label:'实际状态',required:true,options:opts(['in_use'])}]:[]),{key:'reason',label:'核实依据 / 原因',required:true,type:'textarea'}],onSubmit:async v=>{await mutate(`/resources/${r.id}/actions/${action}`,{expected_version:r.version,...v});await changed();notice.value='操作已保存。';}});}
function facts(){const r=row.value!;open({title:'确认初始责任与归属',description:'用于首次核实，不会覆盖已有已确认事实；后续变更请发起治理事项。',fields:[{key:'person_id',label:'负责人',endpoint:'/people'},{key:'company_id',label:'归属公司',endpoint:'/companies'},{key:'source_note',label:'核实来源',required:true,type:'textarea'}],onSubmit:async v=>{await mutate(`/resources/${r.id}/actions/initial-facts`,{expected_version:r.version,source_note:v.source_note,people:v.person_id?[{person_id:v.person_id,role:'owner'}]:[],company_links:v.company_id?[{company_id:v.company_id,role:'owner'}]:[]});await changed();}});}
function relation(){const r=row.value!;open({title:'补充关联',description:'方向为当前资源 → 所选资源；保存为待确认关系。',fields:[{key:'target_id',label:'目标资源',required:true,excludeId:r.id,endpoint:(v:Record<string,string>)=>relationEndpoint(v.relation_type||'uses')},{key:'relation_type',label:'关联类型',required:true,options:opts(['uses','managed_by','part_of','depends_on',...(r.type_code==='business_space'?['contains']:[])])},{key:'note',label:'关系说明',type:'textarea'}],onSubmit:async v=>{await mutate(`/resources/${r.id}/relations`,{expected_version:r.version,...v});await load();await extra();}});}
function declare(){const r=row.value!;open({title:'说明暂缺关系',description:'待了解、不适用与已核实不存在是不同事实。不会创建虚构关联。',fields:[{key:'relation_kind',label:'关系类别',required:true,options:opts(['platform','company','owner','registration','login','recovery','mfa','uses','managed_by','part_of','contains','depends_on'])},{key:'state',label:'事实说明',required:true,options:opts(['unknown','not_applicable','verified_absent'])},{key:'reason',label:'原因',required:true,type:'textarea'},{key:'source',label:'依据来源',required:true}],onSubmit:async v=>{await mutate(`/resources/${r.id}/relation-declarations`,{expected_version:r.version,...v});await load();await extra();}});}
function endRelation(r:DTO<'Stage2ResourceRelationView'>){open({title:'结束关联',description:'已确认的管理类关系需要通过治理流程变更。',fields:[{key:'reason',label:'结束原因',required:true,type:'textarea'}],onSubmit:async v=>{await mutate(`/resources/${id.value}/relations/${r.id}/actions/end`,{expected_version:r.version,reason:v.reason});await load();await extra();}});}
function binding(){const r=row.value!;open({title:'记录身份绑定',description:'登记已知绑定为待确认；已有绑定的变更应进入流程治理。',fields:[{key:'purpose',label:'绑定用途',required:true,options:opts(['registration','login','recovery','mfa'])},{key:'contact_identity_id',label:'已有身份',required:true,endpoint:'/contact-identities'}],onSubmit:async v=>{await mutate(`/resources/${r.id}/bindings`,{expected_version:r.version,...v});await load();await extra();}});}
const tabs=[['facts','基本资料'],['relations','关联'],['materials','使用资料']];
</script>
<template><header class="page-heading"><div><RouterLink to="/resources" class="text-link text-xs">← 资源清单</RouterLink><h1 class="mt-2 break-words">{{row?.name??'资源详情'}}</h1><p v-if="row">{{text(row.type_code)}} · {{row.code}} · v{{row.version}}</p></div><div v-if="row" class="flex flex-wrap gap-2"><RouterLink :to="{path:'/asset-map',query:{kind:'resource',id:row.id}}" class="btn-secondary">查看关系图</RouterLink><RouterLink v-if="editable&&can('governance.write')" :to="{path:'/governance',query:{resource:row.id}}" class="btn-secondary">发起变更</RouterLink><button v-if="editable" class="btn-primary" @click="edit">编辑资料</button></div></header><PageState :error="error" :busy="busy" :notice="notice" @retry="load();extra()"/><template v-if="row"><section class="feishu-section mb-4 p-4"><dl class="detail-grid"><div><dt>生命周期 / 核实</dt><dd>{{text(row.lifecycle)}} · {{text(row.verification)}}</dd></div><div><dt>归属</dt><dd>{{row.confirmed_company?.display_name??'公司待明确'}} / {{row.owning_department?.display_name??'部门待明确'}}</dd></div><div><dt>责任人</dt><dd>{{row.owner?.display_name??'尚未确认'}}</dd></div><div v-if="row.account"><dt>账号标识</dt><dd>{{row.account.identifier??'尚未登记'}}</dd></div><div><dt>用途</dt><dd>{{row.purpose??'待补充'}}</dd></div><div><dt>凭据状态</dt><dd>{{text(row.credential_status)}}</dd></div></dl><div v-if="row.missing_fields.length" class="mt-3 border-t border-gray-100 pt-3 text-xs text-amber-700">待完善：{{row.missing_fields.map(v=>({owner:'负责人',account:'账号标识'}[v]??v)).join('、')}}。不影响已登记事实的查阅。</div></section><section class="feishu-section"><nav class="flex overflow-x-auto border-b border-gray-100" aria-label="资源详情分区"><button v-for="[key,name] in tabs" :key="key" class="task-tab" :class="section===key?'task-tab-active':''" @click="section=key">{{name}}</button><select class="task-tab bg-white" aria-label="更多资源资料" :value="['credentials','bindings','history'].includes(section)?section:''" @change="section=($event.target as HTMLSelectElement).value"><option value="" disabled>更多资料</option><option value="credentials">凭据与授权</option><option v-if="row.account" value="bindings">身份绑定</option><option value="history">来源与历史</option></select></nav><div class="p-4"><template v-if="section==='facts'"><dl class="detail-grid"><div v-if="platform"><dt>所属平台</dt><dd><RouterLink :to="'/directory/platform/'+platform.id" class="text-link">{{platform.name}}</RouterLink></dd></div><div><dt>提供方</dt><dd>{{row.provider_name??'待补充'}}</dd></div><div><dt>可见范围</dt><dd>{{text(row.visibility_scope)}}</dd></div><div><dt>更新于</dt><dd>{{date(row.updated_at)}}</dd></div><div v-for="[key,value] in Object.entries(row.attributes).filter(([,v])=>v!==null&&v!=='')" :key="key"><dt>{{fieldNames[key]??key}}</dt><dd>{{text(value)}}</dd></div><div v-if="row.account"><dt>登录方式 / 账号角色</dt><dd>{{text(row.account.login_methods)}} / {{text(row.account.account_role)}}</dd></div></dl><div v-if="row.subscription_summary" class="mt-4 rounded-lg border border-gray-200 p-3 text-xs"><strong>订阅摘要 · {{row.subscription_summary.plan??'未填套餐'}}</strong><p class="mt-1 text-gray-500">席位 {{row.subscription_summary.seats_assigned??'—'}} / {{row.subscription_summary.seats_total??'—'}} · 当前周期 {{row.subscription_summary.starts_on??'未记录'}} — {{row.subscription_summary.ends_on??'未记录'}}</p><RouterLink v-if="can('finance.read')" :to="{path:'/subscriptions',query:{resource:row.id}}" class="text-link mt-2 inline-block">维护订阅与费用 →</RouterLink></div><h3 class="mb-2 mt-5 text-sm font-medium">责任与使用</h3><p v-if="!row.people.length" class="text-xs text-gray-500">尚未记录人员关系。</p><div v-for="(p,i) in row.people" :key="i" class="flex flex-wrap gap-x-4 gap-y-1 border-b border-gray-100 py-2 text-xs"><span>{{p.person.display_name}}</span><span>{{text(p.role)}}</span><span>{{text(p.confirmation)}}</span><span class="text-gray-500">{{p.valid_to?'结束于 '+date(p.valid_to):'当前有效'}}</span></div><div v-if="editable&&can('governance.confirm')" class="mt-4 flex flex-wrap gap-2"><button v-if="(!row.owner||!row.confirmed_company)" class="btn-secondary" @click="facts">核实初始归属与责任</button><button v-if="row.verification!=='verified'" class="btn-secondary" @click="action('verify')">核实资源</button><button v-if="row.lifecycle==='unknown'" class="btn-secondary" @click="action('confirm-lifecycle')">确认初始状态</button><button v-if="['disabled','retired'].includes(row.lifecycle)" class="btn-secondary" @click="action('archive')">归档</button></div></template><template v-else-if="section==='relations'"><div v-if="editable" class="mb-3 flex flex-wrap gap-2"><button v-if="!['platform_account','mailbox_account'].includes(row.type_code)" class="btn-secondary" @click="relation">补充关联</button><button class="btn-secondary" @click="declare">说明暂缺关系</button></div><p v-if="!related.length&&!declarations.length" class="text-sm text-gray-500">尚无已知关联；不代表已核实没有关系。</p><div v-for="r in related" :key="r.id" class="flex flex-wrap items-center justify-between gap-2 border-b border-gray-100 py-3 text-xs"><div><RouterLink :to="'/resources/'+r.source.id" class="text-link">{{r.source.name}}</RouterLink> → {{text(r.relation_type)}} → <RouterLink :to="'/resources/'+r.target.id" class="text-link">{{r.target.name}}</RouterLink><p class="mt-1 text-gray-500">{{text(r.confirmation)}} · {{r.valid_to?'已结束 '+date(r.valid_to):'当前'}} · {{r.note??'无补充说明'}}</p></div><button v-if="editable&&!r.valid_to&&r.source.id===row.id" class="btn-ghost text-xs" @click="endRelation(r)">结束关系</button></div><div v-for="d in declarations" :key="d.id" class="border-b border-gray-100 py-3 text-xs"><strong>{{text(d.relation_kind)}}：{{text(d.state)}}</strong><p class="mt-1 text-gray-500">{{d.reason}} · 来源 {{d.source}} {{d.ended_at?'（历史说明）':''}}</p></div><Pager :page="page" :total="total" :more="more" @change="page=$event;extra()"/></template><template v-else-if="section==='bindings'"><button v-if="editable&&can('binding.write')" class="btn-secondary mb-3" @click="binding">登记身份绑定</button><div v-for="b in bindings" :key="b.id" class="border-b border-gray-100 py-3 text-sm"><RouterLink :to="'/directory/identity/'+b.contact.id" class="text-link">{{b.contact.masked_value}}</RouterLink><span class="ml-2">{{text(b.purpose)}} · {{text(b.confirmation)}}</span><p class="mt-1 text-xs text-gray-500">{{b.valid_to?'已结束 '+date(b.valid_to):'当前有效'}}</p></div><Pager :page="page" :total="total" :more="more" @change="page=$event;extra()"/></template><CredentialPanel v-else-if="section==='credentials'" :resource="row" @changed="changed"/><MaterialsPanel v-else-if="section==='materials'" :resource="row"/><template v-else-if="section==='history'"><h3 class="mb-2 text-sm font-medium">信息来源</h3><p v-for="s in sources" :key="s.id" class="my-2 text-xs">{{s.label}} · {{text(s.source_kind)}} · {{date(s.created_at)}}</p><h3 class="mb-2 mt-5 text-sm font-medium">操作历史</h3><details v-for="h in history" :key="h.id" class="border-b border-gray-100 py-3"><summary class="cursor-pointer text-xs">{{h.event_type}} · {{date(h.occurred_at)}}</summary><dl class="mt-2 space-y-2 break-words text-xs text-gray-500"><div v-if="h.safe_before">之前：{{text(h.safe_before)}}</div><div v-if="h.safe_after">之后：{{text(h.safe_after)}}</div></dl></details><Pager :page="page" :total="total" :more="more" @change="page=$event;extra()"/></template></div></section></template><TaskForm v-if="form" v-bind="form" @close="form=undefined"/></template>
